arguments.cmd:
mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="Global Aid Alliance provides disaster relief, emergency assistance, and community resilience programs worldwide." />
  <style>
    :root {
      --red-900: #8f1d2c;
      --red-700: #b42b3f;
      --red-600: #c53549;
      --navy-900: #143457;
      --navy-700: #1d4b7c;
      --white: #ffffff;
      --gray-50: #faf8f7;
      --gray-100: #f3efed;
      --gray-300: #d8d0cc;
      --gray-600: #605854;
      --gray-800: #2f2a28;
      --success: #0f6f57;
      --shadow: 0 10px 30px rgba(20, 52, 87, 0.12);
      --radius: 14px;
      --container: min(1160px, 92vw);
    }

    * { box-sizing: border-box; }

    html { scroll-behavior: smooth; }

    body {
      margin: 0;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      color: var(--gray-800);
      background: var(--white);
      line-height: 1.55;
    }

    img { max-width: 100%; display: block; }

    a {
      color: inherit;
      text-decoration: none;
    }

    .container { width: var(--container); margin: 0 auto; }

    .topbar {
      background: var(--red-900);
      color: var(--white);
      font-size: 0.9rem;
      padding: 0.45rem 0;
      text-align: center;
    }

    header {
      position: sticky;
      top: 0;
      z-index: 40;
      background: rgba(255, 255, 255, 0.97);
      border-bottom: 1px solid var(--gray-100);
      backdrop-filter: blur(8px);
    }

    .nav-wrap {
      height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      min-width: 0;
    }

    .brand-mark {
      width: 42px;
      height: 42px;
      border-radius: 50%;
      background: linear-gradient(140deg, var(--red-700), var(--red-900));
      display: grid;
      place-items: center;
      color: var(--white);
      font-weight: 800;
    }

    .brand h1 {
      margin: 0;
      font-size: 1.1rem;
      line-height: 1.1;
      color: var(--navy-900);
    }

    .brand span {
      display: block;
      font-size: 0.75rem;
      color: var(--gray-600);
      font-weight: 500;
    }

    nav ul {
      margin: 0;
      padding: 0;
      list-style: none;
      display: flex;
      align-items: center;
      gap: 1.2rem;
      font-weight: 600;
      color: var(--navy-900);
    }

    nav a:hover,
    nav a:focus-visible { color: var(--red-700); }

    .btn {
      border: 0;
      border-radius: 999px;
      padding: 0.7rem 1.1rem;
      font-weight: 700;
      cursor: pointer;
      transition: 0.22s ease;
      font-size: 0.95rem;
    }

    .btn-primary {
      background: var(--red-700);
      color: var(--white);
      box-shadow: var(--shadow);
    }

    .btn-primary:hover,
    .btn-primary:focus-visible { background: var(--red-600); transform: translateY(-1px); }

    .btn-outline {
      background: transparent;
      color: var(--navy-900);
      border: 1px solid var(--gray-300);
    }

    .btn-outline:hover,
    .btn-outline:focus-visible { border-color: var(--navy-700); color: var(--navy-700); }

    .menu-toggle {
      display: none;
      width: 44px;
      height: 44px;
      border-radius: 10px;
      border: 1px solid var(--gray-300);
      background: var(--white);
      cursor: pointer;
    }

    .menu-toggle span {
      display: block;
      width: 22px;
      height: 2px;
      margin: 4px auto;
      background: var(--navy-900);
      transition: 0.2s;
    }

    .hero {
      background: linear-gradient(135deg, #fff 35%, #fbecee 100%);
      padding: 3.6rem 0 3.2rem;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.1fr 1fr;
      gap: 2rem;
      align-items: center;
    }

    .eyebrow {
      display: inline-block;
      font-size: 0.82rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--red-700);
      font-weight: 700;
      margin-bottom: 0.7rem;
    }

    .hero h2 {
      margin: 0;
      font-size: clamp(2rem, 4.2vw, 3.2rem);
      line-height: 1.1;
      color: var(--navy-900);
    }

    .hero p {
      font-size: 1.05rem;
      color: var(--gray-600);
      margin: 1rem 0 1.5rem;
      max-width: 58ch;
    }

    .hero-actions {
      display: flex;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .hero-media {
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow);
      background: var(--gray-100);
      min-height: 340px;
      position: relative;
    }

    .hero-media img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .hero-chip {
      position: absolute;
      left: 1rem;
      bottom: 1rem;
      background: rgba(20, 52, 87, 0.92);
      color: var(--white);
      padding: 0.5rem 0.8rem;
      border-radius: 999px;
      font-size: 0.83rem;
      font-weight: 600;
    }

    section { padding: 4rem 0; }

    h3.section-title {
      margin: 0 0 0.7rem;
      font-size: clamp(1.5rem, 3vw, 2.1rem);
      color: var(--navy-900);
    }

    .section-sub {
      margin: 0 0 2rem;
      color: var(--gray-600);
      max-width: 70ch;
    }

    .mission-grid {
      display: grid;
      gap: 1.5rem;
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .card {
      background: var(--gray-50);
      border: 1px solid var(--gray-100);
      border-radius: var(--radius);
      padding: 1.2rem;
    }

    .card h4 { margin: 0 0 0.5rem; color: var(--navy-900); }

    .stats {
      background: var(--navy-900);
      color: var(--white);
      padding: 3.5rem 0;
    }

    .stats-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }

    .stat {
      background: rgba(255, 255, 255, 0.08);
      border: 1px solid rgba(255, 255, 255, 0.2);
      border-radius: 12px;
      padding: 1.1rem;
      text-align: center;
    }

    .stat strong {
      display: block;
      font-size: clamp(1.6rem, 3vw, 2.4rem);
      line-height: 1.1;
      color: #fff;
    }

    .stat span { color: #dce6f3; font-weight: 600; font-size: 0.93rem; }

    .accordion {
      border: 1px solid var(--gray-100);
      border-radius: var(--radius);
      overflow: hidden;
      background: var(--white);
    }

    .acc-item + .acc-item { border-top: 1px solid var(--gray-100); }

    .acc-trigger {
      width: 100%;
      padding: 1rem 1.2rem;
      border: 0;
      background: var(--white);
      text-align: left;
      font-weight: 700;
      color: var(--navy-900);
      display: flex;
      justify-content: space-between;
      align-items: center;
      cursor: pointer;
    }

    .acc-trigger .icon { font-size: 1.3rem; color: var(--red-700); transition: transform 0.22s ease; }

    .acc-panel {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.28s ease, padding 0.28s ease;
      padding: 0 1.2rem;
      color: var(--gray-600);
    }

    .acc-item.active .acc-panel { max-height: 220px; padding: 0 1.2rem 1rem; }
    .acc-item.active .icon { transform: rotate(45deg); }

    .involved {
      background: var(--gray-50);
      border-top: 1px solid var(--gray-100);
      border-bottom: 1px solid var(--gray-100);
    }

    .involved-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .news-shell {
      position: relative;
      overflow: hidden;
    }

    .news-track {
      display: flex;
      transition: transform 0.35s ease;
    }

    .news-card {
      min-width: 100%;
      border: 1px solid var(--gray-100);
      border-radius: var(--radius);
      overflow: hidden;
      background: var(--white);
      box-shadow: 0 8px 20px rgba(0,0,0,.05);
    }

    .news-card img {
      width: 100%;
      height: 260px;
      object-fit: cover;
      background: var(--gray-100);
    }

    .news-body { padding: 1rem 1.2rem 1.3rem; }
    .news-body h4 { margin: 0 0 0.4rem; color: var(--navy-900); }
    .news-body p { margin: 0; color: var(--gray-600); }

    .carousel-nav {
      display: flex;
      justify-content: flex-end;
      gap: 0.5rem;
      margin-top: 0.9rem;
    }

    .icon-btn {
      width: 40px;
      height: 40px;
      border-radius: 999px;
      border: 1px solid var(--gray-300);
      background: #fff;
      font-size: 1.2rem;
      cursor: pointer;
    }

    .donate-cta {
      background: linear-gradient(145deg, var(--red-900), var(--red-700));
      color: var(--white);
      text-align: center;
      border-radius: var(--radius);
      padding: 2rem;
    }

    .donate-cta p { margin: 0.6rem auto 1.2rem; max-width: 70ch; color: #f8e8eb; }

    footer {
      background: #1f2127;
      color: #eef2f8;
      padding: 2.6rem 0 2rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1.2rem;
    }

    .footer-grid h5 { margin: 0 0 0.6rem; font-size: 0.95rem; }
    .footer-grid a { color: #d7deea; display: block; margin: 0.38rem 0; font-size: 0.92rem; }
    .footer-grid a:hover { color: #fff; }

    .footnote {
      margin-top: 1.7rem;
      border-top: 1px solid rgba(255,255,255,.18);
      padding-top: 1rem;
      display: flex;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 0.7rem;
      color: #c9d2df;
      font-size: 0.88rem;
    }

    .modal-backdrop {
      position: fixed;
      inset: 0;
      background: rgba(20, 20, 25, 0.62);
      display: none;
      place-items: center;
      z-index: 99;
      padding: 1rem;
    }

    .modal-backdrop.active { display: grid; }

    .modal {
      width: min(560px, 95vw);
      background: #fff;
      border-radius: 16px;
      box-shadow: var(--shadow);
      padding: 1.3rem;
    }

    .modal-top { display: flex; justify-content: space-between; align-items: center; gap: 0.7rem; }
    .modal h4 { margin: 0; color: var(--navy-900); font-size: 1.35rem; }
    .close {
      border: 0;
      width: 36px;
      height: 36px;
      border-radius: 999px;
      font-size: 1.2rem;
      background: var(--gray-100);
      cursor: pointer;
    }

    .amount-grid {
      margin-top: 1rem;
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.6rem;
    }

    .amount-grid button {
      border: 1px solid var(--gray-300);
      background: var(--white);
      border-radius: 10px;
      padding: 0.75rem 0.4rem;
      font-weight: 700;
      cursor: pointer;
    }

    .amount-grid button.selected {
      background: var(--red-700);
      color: var(--white);
      border-color: var(--red-700);
    }

    .donation-form {
      margin-top: 1rem;
      display: grid;
      gap: 0.7rem;
    }

    .donation-form input {
      width: 100%;
      border: 1px solid var(--gray-300);
      border-radius: 10px;
      padding: 0.75rem 0.8rem;
      font: inherit;
    }

    .success-msg {
      display: none;
      margin-top: 0.8rem;
      color: var(--success);
      font-weight: 600;
    }

    .success-msg.show { display: block; }

    .mobile-drawer {
      display: none;
      border-top: 1px solid var(--gray-100);
      background: #fff;
      padding: 0.8rem 0;
    }

    .mobile-drawer a {
      display: block;
      padding: 0.75rem 0;
      color: var(--navy-900);
      font-weight: 600;
    }

    @media (max-width: 980px) {
      nav { display: none; }
      .menu-toggle { display: inline-block; }
      .hero-grid,
      .mission-grid,
      .stats-grid,
      .involved-grid,
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .hero-media { min-height: 260px; }
    }

    @media (max-width: 680px) {
      .nav-wrap { height: 70px; }
      .brand h1 { font-size: 1rem; }
      .hero { padding-top: 2.5rem; }
      .hero-grid,
      .mission-grid,
      .stats-grid,
      .involved-grid,
      .footer-grid,
      .amount-grid { grid-template-columns: 1fr; }
      .mobile-drawer.open { display: block; }
      section { padding: 3rem 0; }
      .news-card img { height: 210px; }
    }
  </style>
</head>
<body>
  <div class="topbar">Emergency Response Hotline: +1 (800) 555-HELP</div>

  <header>
    <div class="container nav-wrap">
      <a href="#home" class="brand" aria-label="Global Aid Alliance home">
        <div class="brand-mark" aria-hidden="true">GA</div>
        <div>
          <h1>Global Aid Alliance</h1>
          <span>Together We Respond</span>
        </div>
      </a>

      <nav aria-label="Primary navigation">
        <ul>
          <li><a href="#mission">About Us</a></li>
          <li><a href="#programs">Disaster Relief</a></li>
          <li><a href="#involved">Volunteer</a></li>
          <li><a href="#news">News</a></li>
          <li><button class="btn btn-primary" data-open-donate>Donate</button></li>
        </ul>
      </nav>

      <button class="menu-toggle" id="menuToggle" aria-label="Open mobile menu" aria-expanded="false" aria-controls="mobileDrawer">
        <span></span><span></span><span></span>
      </button>
    </div>

    <div class="mobile-drawer" id="mobileDrawer">
      <div class="container">
        <a href="#mission">About Us</a>
        <a href="#programs">Disaster Relief</a>
        <a href="#involved">Volunteer</a>
        <a href="#news">News</a>
        <button class="btn btn-primary" data-open-donate>Donate</button>
      </div>
    </div>
  </header>

  <main id="home">
    <section class="hero">
      <div class="container hero-grid">
        <div>
          <span class="eyebrow">Humanitarian Nonprofit</span>
          <h2>When disaster strikes, communities should never stand alone.</h2>
          <p>Global Aid Alliance delivers immediate relief, long-term recovery, and resilience training in crisis-affected regions around the world. Your support helps families access shelter, food, medical care, and hope.</p>
          <div class="hero-actions">
            <button class="btn btn-primary" data-open-donate>Donate Now</button>
            <a class="btn btn-outline" href="#involved">Become a Volunteer</a>
          </div>
        </div>
        <figure class="hero-media">
          <img src="https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?auto=format&fit=crop&w=1200&q=80" alt="Relief workers assisting diverse families after a natural disaster" loading="lazy" />
          <figcaption class="hero-chip">Rapid response in 190 countries</figcaption>
        </figure>
      </div>
    </section>

    <section id="mission" class="container">
      <h3 class="section-title">Our Mission</h3>
      <p class="section-sub">We save lives, reduce suffering, and help communities rebuild with dignity. Through local partnerships and trained responders, we deliver aid where and when it matters most.</p>
      <div class="mission-grid">
        <article class="card">
          <h4>Emergency Response</h4>
          <p>Deploying trained teams with shelter kits, clean water systems, and medical support within hours of major disasters.</p>
        </article>
        <article class="card">
          <h4>Community Resilience</h4>
          <p>Preparing neighborhoods with early warning education, evacuation planning, and resilient infrastructure training.</p>
        </article>
        <article class="card">
          <h4>Global Partnership</h4>
          <p>Working with local organizations and governments to ensure culturally informed, equitable, and effective aid delivery.</p>
        </article>
      </div>
    </section>

    <section class="stats" aria-label="Impact statistics">
      <div class="container">
        <h3 class="section-title" style="color:#fff">Our Impact at a Glance</h3>
        <p class="section-sub" style="color:#dce6f3">Behind every number is a family supported, a volunteer mobilized, and a community recovering.</p>
        <div class="stats-grid">
          <article class="stat"><strong data-counter="12000000" data-suffix="M" data-prefix="">0</strong><span>People Helped</span></article>
          <article class="stat"><strong data-counter="50000" data-suffix="K" data-prefix="">0</strong><span>Volunteers Mobilized</span></article>
          <article class="stat"><strong data-counter="190" data-suffix="" data-prefix="">0</strong><span>Countries Reached</span></article>
          <article class="stat"><strong data-counter="850" data-suffix="M" data-prefix="$">0</strong><span>Raised for Humanitarian Aid</span></article>
        </div>
      </div>
    </section>

    <section id="programs" class="container">
      <h3 class="section-title">Programs & Services</h3>
      <p class="section-sub">Explore our core program areas designed to provide immediate support and build long-term resilience.</p>
      <div class="accordion" id="programAccordion">
        <article class="acc-item active">
          <button class="acc-trigger" aria-expanded="true">Disaster Relief <span class="icon">+</span></button>
          <div class="acc-panel">
            <p>Rapid deployments for hurricanes, floods, earthquakes, and wildfires, including emergency shelter, food distribution, and critical medical supplies.</p>
          </div>
        </article>
        <article class="acc-item">
          <button class="acc-trigger" aria-expanded="false">Blood Donation <span class="icon">+</span></button>
          <div class="acc-panel">
            <p>Community blood drives, donor outreach, and emergency transfusion support to hospitals and clinics in high-need periods.</p>
          </div>
        </article>
        <article class="acc-item">
          <button class="acc-trigger" aria-expanded="false">Emergency Preparedness <span class="icon">+</span></button>
          <div class="acc-panel">
            <p>Training families and schools with evacuation plans, first aid readiness, and disaster simulation exercises for faster, safer response.</p>
          </div>
        </article>
        <article class="acc-item">
          <button class="acc-trigger" aria-expanded="false">International Humanitarian Aid <span class="icon">+</span></button>
          <div class="acc-panel">
            <p>Cross-border coordination for refugee support, emergency health services, and access to clean water and sanitation in conflict and crisis zones.</p>
          </div>
        </article>
        <article class="acc-item">
          <button class="acc-trigger" aria-expanded="false">Community Health <span class="icon">+</span></button>
          <div class="acc-panel">
            <p>Preventive health outreach, mobile clinics, and mental health support services that strengthen recovery and long-term wellbeing.</p>
          </div>
        </article>
      </div>
    </section>

    <section id="involved" class="involved">
      <div class="container">
        <h3 class="section-title">Get Involved</h3>
        <p class="section-sub">Whether you give, volunteer, or partner as an organization, your support helps communities recover faster and stronger.</p>
        <div class="involved-grid">
          <article class="card">
            <h4>Volunteer in Your Area</h4>
            <p>Join local response teams, support shelters, and assist with preparedness workshops.</p>
            <a href="#" style="color: var(--red-700); font-weight:700;">Find Local Chapter</a>
          </article>
          <article class="card">
            <h4>Start a Fundraiser</h4>
            <p>Mobilize your network to fund emergency aid and long-term recovery initiatives.</p>
            <a href="#" style="color: var(--red-700); font-weight:700;">Launch Campaign</a>
          </article>
          <article class="card">
            <h4>Corporate Partnerships</h4>
            <p>Build high-impact alliances through grants, matching gifts, and skills-based volunteering.</p>
            <a href="#" style="color: var(--red-700); font-weight:700;">Partner With Us</a>
          </article>
        </div>
      </div>
    </section>

    <section id="news" class="container">
      <h3 class="section-title">Latest News</h3>
      <p class="section-sub">Follow updates from frontline operations and community stories of resilience.</p>

      <div class="news-shell" aria-roledescription="carousel" aria-label="Latest news stories">
        <div class="news-track" id="newsTrack">
          <article class="news-card">
            <img src="https://images.unsplash.com/photo-1475776408506-9a5371e7a068?auto=format&fit=crop&w=1200&q=80" alt="Emergency teams coordinating hurricane response logistics" loading="lazy" />
            <div class="news-body">
              <h4>Hurricane Response Update</h4>
              <p>Over 45,000 families reached with temporary shelter kits, safe water units, and emergency medical assistance.</p>
            </div>
          </article>
          <article class="news-card">
            <img src="https://images.unsplash.com/photo-1475483768296-6163e08872a1?auto=format&fit=crop&w=1200&q=80" alt="Volunteers distributing relief supplies during wildfire recovery" loading="lazy" />
            <div class="news-body">
              <h4>Wildfire Relief Efforts</h4>
              <p>Mobile support teams continue to provide respiratory care, food delivery, and temporary housing assistance.</p>
            </div>
          </article>
          <article class="news-card">
            <img src="https://images.unsplash.com/photo-1579154204601-01588f351e67?auto=format&fit=crop&w=1200&q=80" alt="Community members participating in a blood donation drive" loading="lazy" />
            <div class="news-body">
              <h4>Blood Drive Campaign</h4>
              <p>Nationwide blood drives collected critical units for emergency surgeries and trauma centers ahead of storm season.</p>
            </div>
          </article>
          <article class="news-card">
            <img src="https://images.unsplash.com/photo-1521737604893-d14cc237f11d?auto=format&fit=crop&w=1200&q=80" alt="Volunteer receiving recognition for humanitarian service" loading="lazy" />
            <div class="news-body">
              <h4>Volunteer Spotlight</h4>
              <p>Meet frontline volunteers whose local leadership has helped communities recover with dignity and hope.</p>
            </div>
          </article>
        </div>
      </div>
      <div class="carousel-nav">
        <button class="icon-btn" id="newsPrev" aria-label="Previous news">←</button>
        <button class="icon-btn" id="newsNext" aria-label="Next news">→</button>
      </div>
    </section>

    <section class="container">
      <div class="donate-cta">
        <h3 class="section-title" style="color:#fff;margin:0;">Your Support Saves Lives</h3>
        <p>91 cents of every dollar goes directly to humanitarian services. Help us reach communities in crisis with urgent aid and long-term recovery support.</p>
        <button class="btn btn-primary" data-open-donate>Donate Now</button>
      </div>
    </section>
  </main>

  <footer>
    <div class="container">
      <div class="footer-grid">
        <div>
          <h5>Programs</h5>
          <a href="#programs">Disaster Relief</a>
          <a href="#programs">Blood Donation</a>
