  <script>
    const menuToggle = document.getElementById('menuToggle');
    const mobileDrawer = document.getElementById('mobileDrawer');

    menuToggle.addEventListener('click', () => {
      const isOpen = mobileDrawer.classList.toggle('open');
      menuToggle.setAttribute('aria-expanded', String(isOpen));
    });

    mobileDrawer.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        mobileDrawer.classList.remove('open');
        menuToggle.setAttribute('aria-expanded', 'false');
      });
    });

    const modal = document.getElementById('donateModal');
    const openDonateButtons = document.querySelectorAll('[data-open-donate]');
    const closeDonate = document.getElementById('closeDonate');
    const amountGrid = document.getElementById('amountGrid');
    const customAmount = document.getElementById('customAmount');
    const donateForm = document.getElementById('donationForm');
    const donateSuccess = document.getElementById('donateSuccess');
    let selectedAmount = null;

    function openModal() {
      modal.classList.add('active');
      document.body.style.overflow = 'hidden';
    }

    function closeModal() {
      modal.classList.remove('active');
      document.body.style.overflow = '';
    }

    openDonateButtons.forEach(btn => btn.addEventListener('click', openModal));
    closeDonate.addEventListener('click', closeModal);

    modal.addEventListener('click', (event) => {
      if (event.target === modal) closeModal();
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && modal.classList.contains('active')) closeModal();
    });

    amountGrid.addEventListener('click', (event) => {
      const button = event.target.closest('button[data-amount]');
      if (!button) return;

      amountGrid.querySelectorAll('button').forEach(item => item.classList.remove('selected'));
      button.classList.add('selected');
      selectedAmount = button.dataset.amount;

      if (selectedAmount !== 'custom') {
        customAmount.value = '';
        customAmount.disabled = true;
      } else {
        customAmount.disabled = false;
        customAmount.focus();
      }
    });

    customAmount.disabled = true;

    donateForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const amount = selectedAmount === 'custom' ? Number(customAmount.value) : Number(selectedAmount);
      if (!amount || amount < 1) {
        alert('Please select or enter a valid donation amount.');
        return;
      }
      donateSuccess.classList.add('show');
      donateForm.reset();
      amountGrid.querySelectorAll('button').forEach(item => item.classList.remove('selected'));
      selectedAmount = null;
      customAmount.disabled = true;
    });

    const counterElements = document.querySelectorAll('[data-counter]');
    let countersStarted = false;

    function formatCounter(value, suffix, prefix) {
      if (suffix === 'M') {
        if (prefix === '$') return `${prefix}${Math.floor(value)}${suffix}`;
        return `${Math.floor(value)}${suffix}`;
      }
      if (suffix === 'K') return `${Math.floor(value / 1000)}${suffix}`;
      return `${prefix || ''}${Math.floor(value)}`;
    }

    function runCounters() {
      if (countersStarted) return;
      countersStarted = true;

      counterElements.forEach((el) => {
        const target = Number(el.dataset.counter);
        const suffix = el.dataset.suffix || '';
        const prefix = el.dataset.prefix || '';
        const duration = 1400;
        const start = performance.now();

        function step(timestamp) {
          const progress = Math.min((timestamp - start) / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          const current = target * eased;
          el.textContent = formatCounter(current, suffix, prefix);
          if (progress < 1) requestAnimationFrame(step);
        }

        requestAnimationFrame(step);
      });
    }

    const statsSection = document.querySelector('.stats');
    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          runCounters();
          statsObserver.disconnect();
        }
      });
    }, { threshold: 0.25 });

    statsObserver.observe(statsSection);

    const acc = document.getElementById('programAccordion');
    acc.addEventListener('click', (event) => {
      const trigger = event.target.closest('.acc-trigger');
      if (!trigger) return;

      const item = trigger.closest('.acc-item');
      const isActive = item.classList.contains('active');
      acc.querySelectorAll('.acc-item').forEach((i) => {
        i.classList.remove('active');
        i.querySelector('.acc-trigger').setAttribute('aria-expanded', 'false');
      });

      if (!isActive) {
        item.classList.add('active');
        trigger.setAttribute('aria-expanded', 'true');
      }
    });

    const newsTrack = document.getElementById('newsTrack');
    const newsItems = newsTrack.children.length;
    const newsPrev = document.getElementById('newsPrev');
    const newsNext = document.getElementById('newsNext');
    let newsIndex = 0;

    function renderNews() {
      newsTrack.style.transform = `translateX(-${newsIndex * 100}%)`;
    }

    newsNext.addEventListener('click', () => {
      newsIndex = (newsIndex + 1) % newsItems;
      renderNews();
    });

    newsPrev.addEventListener('click', () => {
      newsIndex = (newsIndex - 1 + newsItems) % newsItems;
      renderNews();
    });
  </script>
